Translate("deDE", "feralas", {
	title = "Feralas",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Feralas ist die große grüne Wildnis im Südwesten von {link:kalimdor}Kalimdor{/link}. Seine Wälder sind hoch und feucht, seine Flüsse breit, und zwei gewaltige Steinsäulen, die {link:the-twin-colossals}Zwillingskolosse{/link}, ragen über seine nördlichen Hügel. Riesen ziehen über diese nördlichen Hügel. Hippogryphen nisten auf den südlichen Höhen, und Feendrachen huschen durch die Lichtungen. Unter den Bäumen liegen die Ruinen eines älteren Zeitalters, und im Herzen des Waldes stehen die zerbrochenen Hallen von Eldre'Thalas, der Stadt der {red:highborne}Hochgeborenen{/red}, die heute {red:dire-maul}Düsterbruch{/red} heißt. Es ist einer der letzten wilden Orte Kalimdors, und sowohl die {link:alliance}Allianz{/link} als auch die {link:horde}Horde{/link} sind gekommen, um ihn für sich zu beanspruchen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Vor langer Zeit gehörte dieser Wald den {link:night-elves}Nachtelfen{/link}. Ihre Pavillons, Türme und Schreine stehen noch überall in Trümmern, von den {link:ruins-of-solarsal}Ruinen von Solarsal{/link} an der Küste bis zu den gestürzten Steinen der Oberen Wildnis. Das größte ihrer Werke war Eldre'Thalas. Die Stadt überstand die {link:great-sundering}Große Teilung{/link}, doch ihr Prinz, {red:tortheldrin}Tortheldrin{/red}, stillte den Durst seines Volkes nach Magie mit immer dunkleren Mächten. Einige seiner Untertanen erhoben sich gegen ihn. Sie unterlagen und flohen westwärts über das Meer, und ihre Nachfahren sind die {link:skyborne}Skyborne{/link} von {link:zephras-isle}Zephras Isle{/link}. Die Stadt, die zurückblieb, versank langsam in Trümmern. Keine Chronik verzeichnet, wann die letzten Kaldorei das übrige Feralas verließen oder warum.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Nach dem {link:third-war}Dritten Krieg{/link} führte General {link:shandris-feathermoon}Shandris Feathermoon{/link} eine Expedition der {link:sentinels}Schildwachen{/link} nach Feralas und machte die {link:feathermoon-stronghold}Festung Feathermoon{/link} auf einer Insel vor der Westküste zu ihrem Sitz. Ihr Ziel ist klar. Die Armee der Schildwachen hält die {link:horde}Horde{/link} in {link:ashenvale}Eschental{/link} und im {link:stonetalon-mountains}Steinkrallengebirge{/link} zurück, und sie wird nicht zulassen, dass die Horde die letzten wilden Lande hinter ihnen nimmt. Die Horde ist trotzdem gekommen. {link:tauren}Tauren{/link}, {link:orcs}Orcs{/link} und {link:trolls}Trolle{/link} halten {link:camp-mojache}Camp Mojache{/link} im Osten, zwischen den Ogern im Norden und den Gnollen im Süden.

Keine der beiden Seiten ist der einzige Feind des Landes. Die Gordunni-{link:ogres}Oger{/link} vernarben den Wald, wo immer sie sich niederlassen. Die Hatecrest-{link:naga}Naga{/link} graben in den Ruinen an der Küste nach etwas, das niemand versteht. Die Grimmtotem-Tauren fangen Feendrachen, und die {link:gnolls}Gnolle{/link} der Waldpfoten werden mit jeder Jahreszeit verzweifelter. Ihre Verzweiflung hat einen Grund. Im Südosten, an einem Ort namens {link:the-writhing-deep}Die verwundene Tiefe{/link}, haben Insekten aus {link:silithus}Silithus{/link} einen Bau errichtet, und sie breiten sich aus.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:sentinels}Schildwachen{/link} von {link:feathermoon-stronghold}Feathermoon{/link}.{/b} Nachtelfische Kriegerinnen, Druiden, Priesterinnen und Gelehrte unter {link:shandris-feathermoon}Shandris Feathermoon{/link}.
• {b}Die {link:horde}Horde{/link} von {link:camp-mojache}Camp Mojache{/link}.{/b} Taurenjäger, Orckrieger und Hexendoktoren der {link:trolls}Trolle{/link}, die den östlichen Wald halten.
• {b}Die Gordunni-{link:ogres}Oger{/link}.{/b} Ein Stamm, der die Lande nördlich von Camp Mojache und die Ruinen der Oberen Wildnis hält.
• {b}Die Hatecrest-{link:naga}Naga{/link}.{/b} Schlangenvolk der Westküste, der Insel des Schreckens und der {link:ruins-of-solarsal}Ruinen von Solarsal{/link}.
• {b}Die Northspring-{link:harpies}Harpyien{/link}.{/b} Sie hausen in den {link:ruins-of-ravenwind}Ruinen von Rabenwind{/link} im Nordwesten.
• {b}Die {link:gnolls}Gnolle{/link} der Waldpfoten.{/b} Ihre Lager füllen {link:razorfen-downs}die Hügel{/link} südlich von Camp Mojache.
• {b}Die {link:grimtotem-clan}Grimmtotem{/link}.{/b} {link:tauren}Tauren{/link}, die {link:cairne-bloodhoof}Cairne Bloodhoof{/link} ablehnen, mit einem Lager im östlichen Wald.
• {b}Die Zukk'ash.{/b} Insekten von der Art der {link:qiraji}Silithiden{/link}, in der Verwundenen Tiefe.
• {b}Die Geschöpfe der Wildnis.{/b} Bergriesen, Treants, Hippogryphen, Sprite Darter, Yetis, Groddoc-Affen und Eisenpelzbären.
• {b}Die grünen Drachkin.{/b} Hüter des Traum-Geästs im Norden, des Tores zum {link:emerald-dream}Smaragdgrünen Traum{/link}.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das Zeitalter der Elfen.{/b} Die {link:night-elves}Nachtelfen{/link} und die Hochgeborenen bauten überall im Wald. Eldre'Thalas war ihre Krone.
• {b}Die Rebellion von Eldre'Thalas.{/b} Nach dem {link:war-of-the-ancients}Krieg der Ahnen{/link} erhoben sich Rebellen gegen Prinz Tortheldrin und flohen in den Himmel. Der Prinz behielt seine Stadt.
• {b}Das Lange Schweigen.{/b} Zeitalter lang blieb der Wald den Tieren, den Ogern und dem Verfall überlassen.
• {b}Die Ankunft der {link:sentinels}Schildwachen{/link}.{/b} Nach dem Dritten Krieg führte {link:shandris-feathermoon}Shandris Feathermoon{/link} ihre Expedition nach Süden und machte die {link:feathermoon-stronghold}Festung Feathermoon{/link} zu ihrem {link:the-bulwark}Bollwerk{/link}.
• {b}Die Gegenwart.{/b} Die {link:horde}Horde{/link} hält {link:camp-mojache}Camp Mojache{/link}. {link:naga}Naga{/link}, {link:ogres}Oger{/link}, {link:harpies}Harpyien{/link} und {link:gnolls}Gnolle{/link} drängen von allen Seiten, und im Süden wächst ein Insektenbau.]=],
		},
		{
			title = "Überlieferungen der Wildnis",
			text = [=[• Die {link:trolls}Trolle{/link} von {link:camp-mojache}Camp Mojache{/link} sagen, dass ein gewaltsam getötetes Tier seinen Muisek zurücklässt, einen Geist, der entkommen und in größerer und rachsüchtigerer Gestalt zurückkehren kann.
• Gelehrte, die aus {link:thousand-needles}Tausend Nadeln{/link} kommen, bemerken, dass das Grün von Feralas an den Schluchten so scharf endet wie eine gezogene Linie.
• Ein Buch namens {i}Feralas: Eine Geschichte{/i} wird von einer Hüterin des Wissens in {link:rut-theran-village}Rut'theran{/link} unterhalb von {link:teldrassil}Teldrassil{/link} verwahrt. Nach ihrem Bericht haben {link:ogres}Oger{/link} und {link:harpies}Harpyien{/link} alles wirklich Wertvolle aus den Ruinen schon vor langer Zeit fortgeschafft.
• Ein Goblin-Ingenieur an der Vergessenen Küste nennt sie den schlechtesten Ort der Welt, um einen Laden zu eröffnen.]=],
		},
	},
})

Translate("deDE", "feathermoon-stronghold", {
	title = "Festung Feathermoon",
	aliases = { "Feathermoon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Festung Feathermoon steht auf der Insel Sardor vor der Westküste von {link:feralas}Feralas{/link}. Sie ist der Sitz von General {link:shandris-feathermoon}Shandris Feathermoon{/link} und das südliche {link:the-bulwark}Bollwerk{/link} der {link:sentinels}Schildwachen{/link}. Ihre Mauern schützen Kriegerinnen und Bogenschützinnen, einen Druiden in einem Baumhaus, eine Priesterin und Gelehrte, zwei Erforscher von Ruinen sowie die Lederer und Händler, die die Besatzung mit Nahrung und Schuhwerk versorgen. Hippogryphen tragen ihre Reisenden quer durch {link:kalimdor}Kalimdor{/link}. Die Festung ist stark, doch nicht leicht zu halten: {link:naga}Naga{/link} haben die Ruinen im Süden derselben Insel eingenommen, und die {link:horde}Horde{/link} ist nie fern. Ein Exemplar von {red:the-sentinels-and-the-long-vigil}The Sentinels and the Long Vigil{/red} wird hier verwahrt.]=],
		},
	},
})

Translate("deDE", "ruins-of-solarsal", {
	title = "Ruinen von Solarsal",
	aliases = { "Solarsal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Solarsal liegen am Südende der Insel Sardor, einen kurzen Marsch von der {link:feathermoon-stronghold}Festung Feathermoon{/link} entfernt. Sie sind älter als jede lebende Erinnerung. Die {link:sentinels}Schildwachen{/link} durchsuchten sie bei ihrer Ankunft, fanden nichts und ließen sie in Frieden. Dann kamen die Hatecrest-{link:naga}Naga{/link} in großer Zahl. Im Herzen der Ruinen steht ein Pavillon, der sichtlich jünger ist als die Steine um ihn herum. Seine Seiten tragen eine Reihe sich wiederholender Glyphen, die kein Gelehrter lesen kann, und sein Stein ist warm, wenn man ihn berührt.]=],
		},
	},
})

Translate("deDE", "isle-of-dread", {
	title = "Die Insel des Schreckens",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Insel des Schreckens liegt jenseits des Wassers südlich der Insel Sardor. Hatecrest-{link:naga}Naga{/link} halten ihre Ufer, und in einer Höhle im Süden haben sie gegraben. Aus dieser Grabung holte ihr {link:lord-shalzaru}Lord Shalzaru{/link} ein seltsames Relikt, das die Gelehrten von {link:feathermoon-stronghold}Feathermoon{/link} nicht einordnen konnten. Noch weiter im Süden gehört die Insel den Chimaerok, großen Bestien, die den Süden der Insel durchstreifen, und einem ungeheuren Lord ihrer Art namens Lakmaeran.]=],
		},
	},
})

Translate("deDE", "the-forgotten-coast", {
	title = "Die vergessene Küste",
	aliases = { "Vergessene Küste" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die vergessene Küste ist das lange Westufer von {link:feralas}Feralas{/link}, das jenseits der Meerenge {link:feathermoon-stronghold}Feathermoon{/link} gegenüberliegt. Ihre Strände sind wild und ihre Gewässer unruhig. Elementare des Meeres steigen aus der Brandung, und sie haben mehr als ein Boot zerschmettert, das sich dicht an der Küste hielt. Ein einziger Anleger steht an der Küste. Ein Goblin des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link} hat daneben gegen jede Vernunft seine Ingenieurswerkstatt eingerichtet, und ein verirrter gnomischer Roboter wurde einst dorthin gebracht, um auf seine Rettung zu warten.]=],
		},
	},
})

Translate("deDE", "camp-mojache", {
	title = "Camp Mojache",
	aliases = { "Mojache" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Camp Mojache ist der Stützpunkt der {link:horde}Horde{/link} in {link:feralas}Feralas{/link}, ein Lager im östlichen Wald. {link:tauren}Tauren{/link}, {link:orcs}Orcs{/link} und {link:trolls}Trolle{/link} leben dort Seite an Seite. Das Lager wird von zwei Seiten bedrängt. Gordunni-{link:ogres}Oger{/link} halten die Flusslande im Norden, und die {link:gnolls}Gnolle{/link} der Waldpfoten fallen aus den Hügeln im Süden ein, mit jeder Jahreszeit heftiger. Seine Krieger halten die Linie, seine Jäger spüren durch den Wald, sein Hexendoktor vollzieht seltsame Riten, und seine Lederer zahlen gut für Yetifelle. Windreiter verbinden es mit dem Rest der Horde.]=],
		},
	},
})

Translate("deDE", "thalanaar", {
	title = "Thalanaar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thalanaar ist eine kleine Raststation der {link:night-elves}Nachtelfen{/link} im äußersten Südosten von {link:feralas}Feralas{/link}, wo der Wald am Rand von {link:thousand-needles}Tausend Nadeln{/link} endet. Kuriere aus {link:feathermoon-stronghold}Feathermoon{/link} tragen ihre Vorräte quer durch die ganze Breite des Waldes, einen langen Weg durch die Lande der {link:horde}Horde{/link}, der {link:gnolls}Gnolle{/link} und Schlimmerer. Der Druide {link:falfindel-waywarder}Falfindel Waywarder{/link} hütet sie, und ein Hippogryphenmeister und eine Lederin des alten Stammeshandwerks leben neben ihm.]=],
		},
	},
})

Translate("deDE", "the-twin-colossals", {
	title = "Die Zwillingskolosse",
	aliases = { "Zwillingskolosse" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Zwillingskolosse sind zwei aufragende Felssäulen im Norden von {link:feralas}Feralas{/link}, die Ostsäule und die Westsäule. Bergriesen ziehen über das steinige Land zu ihren Füßen, und der Boden bebt, wo sie vorübergehen. Eine, die nahe den Säulen lebt, kann einen Reisenden auf die Spitze einer von ihnen schicken, warnt aber, dass sie niemanden wieder herunterholen kann. Ein Riese namens {link:rockbiter}Rockbiter{/link} hat in ihrem Schatten sein Lager.]=],
		},
	},
})

Translate("deDE", "ruins-of-ravenwind", {
	title = "Ruinen von Rabenwind",
	aliases = { "Rabenwind" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen von Rabenwind liegen im Nordwesten von {link:feralas}Feralas{/link}, auf dem Festland westlich des Traum-Geästs. Heute hausen dort die Northspring-{link:harpies}Harpyien{/link}, und an den Hatetalon-Steinen im Norden der Ruinen kann man ihre Königin herbeirufen. Ältere Dinge sind geblieben. Vier Flammen brennen noch zwischen den Steinen, Samha, Imbel, Byltan und Lahassa genannt, und zwischen ihnen steht der Equinex-Monolith, ein versiegelter Stein, der sich nur einem Stab öffnet, der mit ihrem Feuer geladen ist. Etwas war in ihm verborgen.]=],
		},
	},
})

Translate("deDE", "dream-bough", {
	title = "Traum-Geäst",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Traum-Geäst ist ein großer Baum auf einer Insel im Jademirsee, im äußersten Norden von {link:feralas}Feralas{/link}. Es ist eines der Tore zum {link:emerald-dream}Smaragdgrünen Traum{/link}. Seine Hüter sind Drachkin des grünen Schwarms: Orakel, Baumwärter und Astwächter, die niemanden heranlassen, und über ihnen große grüne Drachen wie {link:lethlas}Lethlas{/link} und Dreamroarer. Das Land um den See heißt Oneiros.]=],
		},
	},
})

Translate("deDE", "rage-scar-hold", {
	title = "Wutschrammfeste",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Wutschrammfeste liegt im nördlichen Wald von {link:feralas}Feralas{/link}. Sie ist die Heimat der wildesten Yetis des Waldes. Die Ältesten der Wutschramm sind größer und grimmiger als ihre Vettern im Südwesten, und ihre Felle sind dicker. Lederer aus {link:feathermoon-stronghold}Feathermoon{/link} wie aus {link:camp-mojache}Camp Mojache{/link} glauben, dass solche Felle, richtig gegerbt, härter als Eisen sein können, und sie zahlen gut für jedes, das sie erreicht.]=],
		},
	},
})

Translate("deDE", "feral-scar-vale", {
	title = "Wildschrammtal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Wildschrammtal ist ein Tal westlich von {link:camp-mojache}Camp Mojache{/link} und die erste Heimat der Yetis von {link:feralas}Feralas{/link}. Die Tiere sind dort häufig, und Jäger beider Fraktionen jagen ihre dicken Felle. In einer Höhle nahe dem Tal lag einst ein gnomischer Suchroboter abgestürzt und zerbrochen, bis ein Reisender dem Ruf seines Erbauers folgte und ihn zur Küste geleitete.]=],
		},
	},
})

Translate("deDE", "gordunni-outpost", {
	title = "Außenposten der Gordunni",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Außenposten der Gordunni liegt flussaufwärts nördlich von {link:camp-mojache}Camp Mojache{/link}. Er ist die nächste Festung der Gordunni-{link:ogres}Oger{/link}, und das Land um ihn zeigt ihren Durchzug in gefällten Bäumen und verdorbenem Boden. Die Oger vergraben dort ein blau leuchtendes Erz, Gordunni-Kobalt, und bewachen es erbittert. Beschmutzte Schriftrollen aus dem Außenposten beschreiben eine Zeremonie, die von den Magierlords des Stammes geleitet wird.]=],
		},
	},
})

Translate("deDE", "high-wilderness", {
	title = "Die obere Wildnis",
	aliases = { "Ruinen von Isildien", "Isildien" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die obere Wildnis ist das Hochland südwestlich von {link:camp-mojache}Camp Mojache{/link}. Einst gehörte es den {link:night-elves}Nachtelfen{/link}, und ihre Türme stehen dort noch, zerbrochen und verlassen, in den Ruinen von Isildien. Die Gordunni haben es eingenommen. Ihre Schamanen und Hexenmeister wirken ihre Magie zwischen den Steinen, und die Bäume um sie verdorren. Die {link:ogres}Oger{/link} der Oberen Wildnis sind stärker als die des nördlichen Außenpostens, und die Magierlords des Stammes versammeln sich dort.]=],
		},
	},
})

Translate("deDE", "frayfeather-highlands", {
	title = "Fransenfederhochland",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Fransenfederhochland erhebt sich im Süden von {link:feralas}Feralas{/link}, neben der Oberen Wildnis. Es ist nach den wilden Hippogryphen benannt, die dort nisten, von jungen Hirschschwingen bis zu alten Patriarchen. Der Hippogryph ist seit langem ein Freund der {link:night-elves}Nachtelfen{/link}, treu und standhaft, und darum jagen die {link:trolls}Trolle{/link} von {link:camp-mojache}Camp Mojache{/link} diese wilden Tiere um der Stärke ihrer Geister willen.]=],
		},
	},
})

Translate("deDE", "grimtotem-compound", {
	title = "Truppenlager der Grimmtotem",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Truppenlager der Grimmtotem ist ein Lager der {link:grimtotem-clan}Grimmtotem{/link}-{link:tauren}Tauren{/link} im östlichen Wald, westlich von {link:camp-mojache}Camp Mojache{/link}. Seine Naturkundler, Plünderer und Schamanen haben Sprite Darter gefangen, die Feendrachen von {link:feralas}Feralas{/link}, und halten sie in Bambuskäfigen eingesperrt. Niemand weiß, was sie mit ihnen wollen. Zwei {link:night-elves}Nachtelfen{/link} beobachten das Lager vom Grat darüber, und die {link:horde}Horde{/link} von Mojache setzte, als sie erfuhr, dass die Grimmtotem hier waren, einen Preis auf ihre Hörner aus.]=],
		},
	},
})

Translate("deDE", "lariss-pavilion", {
	title = "Lariss' Pavillon",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lariss' Pavillon ist eine Elfenruine im Osten von {link:feralas}Feralas{/link}, nördlich von {link:camp-mojache}Camp Mojache{/link}. Seine alten Steine sind zur Zuflucht von {link:azj-tordin}Azj'Tordin{/link} geworden, einem Ältesten, der aus Eldre'Thalas und vor dessen gefallenem Prinzen floh. Er lebt dort still, und von seinem alten Leben ist ihm wenig geblieben außer seiner Gelehrsamkeit.]=],
		},
	},
})

Translate("deDE", "woodpaw-hills", {
	title = "Waldpfotenhügel",
	aliases = { "Waldpfotenbau" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Waldpfotenhügel liegen südlich von {link:camp-mojache}Camp Mojache{/link}, und die {link:gnolls}Gnolle{/link} des Rudels der Waldpfoten füllen sie mit {link:camping}Lagern{/link} und Bauten. Jahrelang waren ihre Überfälle auf das Lager nur lästig. In letzter Zeit sind sie rasend geworden. Ihre eigenen Schlachtpläne zeigen, warum: Der größte Teil ihrer Stärke ist nach Süden gewandt, gegen die Insekten der Verwundenen Tiefe, und sie verlieren. Ein Krieg an zwei Fronten hat sie verzweifelt gemacht.]=],
		},
	},
})

Translate("deDE", "the-writhing-deep", {
	title = "Die verwundene Tiefe",
	aliases = { "Verwundene Tiefe" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die verwundene Tiefe ist ein Insektenbau im äußersten Südosten von {link:feralas}Feralas{/link}. Ihr Boden ist zu Hügeln und Tunneln verdreht, und es wimmelt darin von Zukk'ash: Stachlern, Wespen, Arbeitern und Tunnelgräbern. Die Gelehrten von {link:darnassus}Darnassus{/link} wie von {link:orgrimmar}Orgrimmar{/link} nennen sie {link:qiraji}Silithiden{/link}, Verwandte der Schwärme von {link:silithus}Silithus{/link}. Sie versiegeln ihre Gefangenen lebendig in Hülsen aus gehärtetem Schleim. Ein Riese unter ihnen, {link:stinglasher}Stinglasher{/link} genannt, zieht durch den Bau, umhüllt von einer Aura, die seine geringeren Artgenossen nicht teilen.]=],
		},
	},
})

Translate("deDE", "shandris-feathermoon", {
	title = "Shandris Feathermoon",
	subtitle = "General der Armee der Schildwachen",
	found = "Festung Feathermoon, im Hauptgebäude",
	hint = [=[Sucht die Generalin der Schildwachen in ihrer Inselfestung vor der Westküste auf.]=],
	allegiance = "Schildwachen · Darnassus",
	aliases = { "Shandris", "General Feathermoon" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shandris Feathermoon ist die Generalin der Armee der {link:sentinels}Schildwachen{/link}, das Schwert von {link:tyrande-whisperwind}Tyrande Whisperwind{/link} und die erste Soldatin der {link:night-elves}Nachtelfen{/link}. Sie befehligt nicht von {link:darnassus}Darnassus{/link} aus. Sie hat ihren Sitz in der {link:feathermoon-stronghold}Festung Feathermoon{/link} genommen, auf einer Insel vor der Küste von {link:feralas}Feralas{/link}, am südlichen Rand der Lande, die ihr Volk noch bewacht. Ihre Stimme ist knapp, ihre Worte sind wenige, und wer ihr gut dient, wird bedankt, bezahlt und wieder ausgesandt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die {link:sentinels}Schildwachen{/link} sind das Heer eines Volkes, das in diesem Zeitalter nie eines hätte brauchen sollen. Seit dem {link:third-war}Dritten Krieg{/link} kämpfen sie gegen die {link:horde}Horde{/link} in {link:ashenvale}Eschental{/link} und im {link:stonetalon-mountains}Steinkrallengebirge{/link}, und Shandris hält diese Linie über ganz {link:kalimdor}Kalimdor{/link}. {link:feralas}Feralas{/link} ist ihre Antwort auf eine größere Frage: Was wird von der wilden Welt bleiben, wenn der Krieg endet? Sie kam nach Süden, um die letzten grünen Lande des Kontinents aus den Händen der Horde zu halten, und sie gedenkt, sie zu halten.

Ihre Geschichten reichen weiter zurück als jeder Krieg der Gegenwart. Man erzählt, sie sei ein Kind gewesen, als der {link:war-of-the-ancients}Krieg der Ahnen{/link} ihre Welt zerbrach, eine Waise, die die junge Priesterin {link:tyrande-whisperwind}Tyrande{/link} in ihre Obhut nahm.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie führte die Expedition der {link:sentinels}Schildwachen{/link} nach {link:feralas}Feralas{/link} und erbaute die {link:feathermoon-stronghold}Festung Feathermoon{/link}.
• Sie schickte Späher in die {link:ruins-of-solarsal}Ruinen von Solarsal{/link}, als sich die Hatecrest-{link:naga}Naga{/link} dort sammelten, und übertrug den Feldzug gegen die Naga ihrem Stellvertreter {link:latronicus-moonspear}Latronicus Moonspear{/link}.
• Sie hat sich geweigert, ihre ganze Streitmacht gegen die Naga zu werfen, aus Furcht, die Festung der {link:horde}Horde{/link} oder etwas Schlimmerem offen zu lassen.
• Sie sandte Nachricht vom Bau der Zukk'ash nach {link:darnassus}Darnassus{/link} und eine Abschrift des Berichts des Kuriers {link:raschal-the-courier}Raschal{/link} an die Priesterin Gracina Spiritmight vom {link:temple-of-the-moon}Tempel des Mondes{/link}.
• Der Druide {link:quintis-jonespyre}Quintis Jonespyre{/link} nennt sie zusammen mit dem Protektorat unter den Kollegen, die den Hunger des Erzdruiden nach Morrowgrain in Frage stellen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine bisher geschriebene Chronik sagt, wann Shandris zur Generalin ernannt wurde oder was sie im Dritten Krieg selbst tat. Die Geschichten ihrer Kindheit stammen aus den Chroniken des Krieges der Ahnen, nicht aus ihrem eigenen Mund.]=],
		},
	},
	chapters = {
		{
			title = "Der warme Stein",
			hint = [=[Durchsucht die alten Ruinen im Süden der Insel der Generalin.]=],
			text = [=[Shandris hatte die {link:ruins-of-solarsal}Ruinen von Solarsal{/link} für leer gehalten. Als die {link:naga}Naga{/link} in großer Zahl dorthin kamen, hielt sie es zuerst für den Beginn eines Angriffs, doch sie war sich nicht sicher. Der Bericht, der zurückkam, beschrieb einen Pavillon, jünger als die Ruinen, Glyphen, die niemand lesen konnte, und Stein, der unter der Hand warm war. Sie nannte es beunruhigend. Was immer die Naga vorhatten, sie wusste nun, dass sie bleiben wollten.]=],
		},
		{
			title = "Gegen die Hatecrest",
			hint = "Folgt dem Ruf der Generalin gegen die Naga.",
			text = [=[Shandris wog die Sache ab, wie es eine Generalin muss. Sie wollte die {link:naga}Naga{/link} mit jeder Klinge treffen, die sie hatte. Sie wusste aber auch, wozu eine leere Festung einladen würde. Am Ende übertrug sie die Aufgabe {link:latronicus-moonspear}Latronicus{/link}, der die Naga am längsten beobachtet hatte, und behielt selbst den größeren Krieg im Auge.]=],
		},
		{
			title = "Der Aufstieg der Silithiden",
			hint = "Empfangt den Dank der Generalin für die Rettung des Kuriers.",
			text = [=[Als {link:raschal-the-courier}Raschal{/link} lebend aus der Verwundenen Tiefe heimkehrte, dankte Shandris seinen Rettern selbst. Dann wandte sie sich sogleich seinem Bericht zu. Insekten, die lebende Elfen in Hülsen versiegeln, waren keine Sache für eine einzelne Festung. Sie sandte den Bericht nach {link:darnassus}Darnassus{/link} und eine Abschrift an eine Priesterin, die solche Geschöpfe kannte, und bat Elune, über sie alle zu wachen.]=],
		},
	},
	mentions = {
		{ text = "Die {link:ruins-of-solarsal}Ruinen von Solarsal{/link}" },
		{
			text = [=[Rückkehr zur {link:feathermoon-stronghold}Festung Feathermoon{/link}]=],
		},
		{ text = "Gegen die Hatecrest" },
		{ text = "Der Empfang eines Helden" },
		{ text = "Der Aufstieg der {link:qiraji}Silithiden{/link}" },
		{ text = "Jonespyres Bitte, die sie unter dem Protektorat nennt" },
	},
	bonds = {
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "ihre Hohepriesterin" },
		{ id = "latronicus-moonspear", name = "Latronicus Moonspear", note = "ihr Stellvertreter" },
		{ id = "ginro-hearthkindle", name = "Ginro Hearthkindle", note = "suchte ihren verschollenen Kurier" },
		{ id = "quintis-jonespyre", name = "Quintis Jonespyre", note = "ihr Kollege im Protektorat" },
		{ id = "raschal-the-courier", name = "Raschal der Kurier", note = "ihr Kurier" },
		{ id = "hadoken-swiftstrider", name = "Hadoken Swiftstrider", note = "hält das Lager der Horde im Osten" },
	},
})

Translate("deDE", "latronicus-moonspear", {
	title = "Latronicus Moonspear",
	subtitle = "Stellvertreter von Feathermoon",
	found = "Festung Feathermoon, an der Seite der Generalin",
	hint = [=[Sprecht mit dem Offizier, der in Feathermoon an der Seite der Generalin steht.]=],
	allegiance = "Schildwachen · Festung Feathermoon",
	aliases = { "Latronicus", "Latro" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Latronicus Moonspear ist der Stellvertreter des Befehlshabers der {link:feathermoon-stronghold}Festung Feathermoon{/link} und der Offizier, der die Hatecrest-{link:naga}Naga{/link} am längsten beobachtet hat. Er ist ein praktischer Soldat. Er schätzt jene, die Dinge erledigen, zahlt seine Kopfgelder ohne Klage aus der Kasse der Festung und gibt offen zu, dass die Rätsel alter Relikte ihn übersteigen. Diese schickt er zu seiner Frau.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wo {link:shandris-feathermoon}Shandris{/link} an den ganzen Krieg denkt, denkt Latronicus an die Insel. Sein Feldzug gegen die {link:naga}Naga{/link} ist ein kleiner Krieg für sich, geführt um die Insel Sardor und die Gewässer um sie herum. Er hat auch ein wachsames Auge auf den Missbrauch von Magie und spricht von Elfen, die sich für ihre Meister halten, als Sklaven ihres eigenen Hungers.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt den Kampf gegen die Hatecrest-{link:naga}Naga{/link} auf der Insel Sardor und der Insel des Schreckens.
• Er erfuhr von seinen Spähern, dass die Naga von Adligen geführt wurden, und bestimmte {link:lord-shalzaru}Lord Shalzaru{/link} zum Tode.
• Er erklärte den Kurier {link:raschal-the-courier}Raschal{/link} für vermisst und schickte Suchende zu {link:ginro-hearthkindle}Ginro Hearthkindle{/link}.
• Er will das Netz der Magierin Lethtendris aus {red:dire-maul}Düsterbruch{/red} geholt haben, damit die darin gefangene Magie in die Wildnis zurückkehren kann.]=],
		},
	},
	chapters = {
		{
			title = "Der Adel der Naga",
			hint = "Brecht den Griff der Naga um die Inseln bei Feathermoon.",
			text = [=[Latronicus plante seinen Krieg in zwei Teilen: die {link:naga}Naga{/link} in ihrer Zahl und in ihrer Führung schwächen und erfahren, wonach sie gruben. Zuerst kamen die Schuppen. Dann nannten seine Späher einen grausamen Nagalord, {link:lord-shalzaru}Shalzaru{/link}, der ein seltsames Relikt aus einer Höhle auf der Insel des Schreckens geholt hatte. Als Shalzaru fiel, glaubte Latronicus, die Naga würden lange in Unordnung sein. Das Relikt konnte er überhaupt nicht deuten.]=],
		},
		{
			title = "Das Relikt",
			hint = "Bringt das Relikt der Naga zur Gelehrten von Feathermoon.",
			text = [=[Er bat darum, das Relikt zu seiner Frau {link:vestia-moonspear}Vestia{/link} zu bringen, die er die beste Gelehrte in allen Landen nennt. Er musste wissen, was es war. Die {link:naga}Naga{/link}, so vermutete er, ebenfalls.]=],
		},
	},
	mentions = {
		{ text = "Gegen die Hatecrest" },
		{ text = "Gegen {link:lord-shalzaru}Lord Shalzaru{/link}" },
		{ text = "Die Übergabe des Relikts" },
		{ text = "Der vermisste Kurier" },
		{ text = "Lethtendris' Netz" },
	},
	bonds = {
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "seine Generalin" },
		{ id = "vestia-moonspear", name = "Vestia Moonspear", note = "seine Frau" },
		{ id = "lord-shalzaru", name = "Lord Shalzaru", note = "Feind" },
		{ id = "ginro-hearthkindle", name = "Ginro Hearthkindle", note = "ein Gefährte" },
	},
})

Translate("deDE", "vestia-moonspear", {
	title = "Vestia Moonspear",
	subtitle = "Priesterin und Gelehrte von Feathermoon",
	found = "Festung Feathermoon, zwischen ihren Büchern",
	hint = [=[Sucht die Priesterin, die in einem stillen Winkel von Feathermoon studiert.]=],
	allegiance = "Schildwachen · Festung Feathermoon",
	aliases = { "Vestia" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vestia Moonspear ist eine Priesterin Elunes und die Frau von {link:latronicus-moonspear}Latronicus{/link}. Ihr Mann nennt sie eine der gelehrtesten Forscherinnen überhaupt, und er bringt ihr jedes Rätsel, das er nicht lösen kann. Das größte davon ist das Relikt, das {link:lord-shalzaru}Lord Shalzaru{/link} abgenommen wurde.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vestia sprach als Erste laut aus, was das Relikt bedeuten könnte. Es gehörte nicht zu den Ruinen, aus denen es stammte, und es war nicht von {link:naga}Naga{/link} gefertigt. Es war etwas Fremderes als beides.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie dient {link:feathermoon-stronghold}Feathermoon{/link} als Priesterin.
• Sie hat das Relikt der {link:naga}Naga{/link} zur Untersuchung genommen und weiß noch nicht, was es ist.]=],
		},
	},
	mentions = {
		{ text = "Die Übergabe des Relikts" },
	},
	bonds = {
		{ id = "latronicus-moonspear", name = "Latronicus Moonspear", note = "ihr Mann" },
		{ id = "lord-shalzaru", name = "Lord Shalzaru", note = "fand das Relikt, das sie untersucht" },
	},
})

Translate("deDE", "ginro-hearthkindle", {
	title = "Ginro Hearthkindle",
	subtitle = "Sucher von Feathermoon",
	found = "Festung Feathermoon, in seinem Quartier",
	hint = [=[Findet die Schildwache, die nicht aufhört, nach einem verschollenen Kurier zu suchen.]=],
	allegiance = "Schildwachen · Festung Feathermoon",
	aliases = { "Ginro", "Gin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ginro Hearthkindle ist ein Soldat der {link:feathermoon-stronghold}Festung Feathermoon{/link}, der einen Freund nicht aufgeben wollte. Als der Kurier {link:raschal-the-courier}Raschal{/link} auf dem Weg nach {link:thalanaar}Thalanaar{/link} verschwand, zog Ginro jeden Tag in die Wildnis hinaus, um ihn zu finden, und kam jeden Abend mit nichts als Gnollzähnen zurück. Selbst nachdem die Festung Raschal für verloren erklärt hatte, suchte er weiter.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ginros Suche deckte die größte Gefahr in {link:feralas}Feralas{/link} auf. Auf der Spur eines verschollenen Kuriers fanden die Suchenden den Bau der Zukk'ash, das erste Zeichen der {link:qiraji}Silithiden{/link} des Südens in diesen Landen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er suchte {link:raschal-the-courier}Raschal{/link} Tag für Tag, allein.
• Er schickte das Messer des Kuriers dem Druiden {link:quintis-jonespyre}Quintis Jonespyre{/link}, damit es durch Berührung gelesen würde, und bezahlte dafür, indem er eine Spielschuld erließ.
• Er drängte auf einen direkten Angriff auf die Lager der Waldpfoten, sobald die Vision des Druiden dorthin wies.
• Er brachte Raschals Retter vor {link:shandris-feathermoon}Shandris Feathermoon{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Das Wrack",
			hint = "Durchsucht die Küste von Feralas nach dem Boot des Kuriers.",
			text = [=[{link:raschal-the-courier}Raschal{/link} hatte die Küste hinabrudern und den Süden von {link:feralas}Feralas{/link} durchqueren wollen, um dem Lager der {link:horde}Horde{/link} fernzubleiben. Sein Boot wurde gesunken und aufgerissen gefunden, das Wappen der Festung noch an der Seite. Im Schlamm darunter lag sein Messer. Etwas im Wasser hatte das Boot beinahe entzweigebrochen.]=],
		},
		{
			title = "Das enthüllte Messer",
			hint = "Erfahrt, woran sich das Messer des Kuriers erinnert.",
			text = [=[{link:quintis-jonespyre}Quintis{/link} hielt das Messer und sah {link:raschal-the-courier}Raschal{/link} zwei Bündel landeinwärts tragen, den Waldpfoten begegnen und voller Furcht zu seinem Boot zurückkehren. Raschal fürchtete nichts, was die {link:gnolls}Gnolle{/link} tun konnten. Etwas anderes hatte ihn erschreckt, so sehr, dass er das Wasser nie hinter sich aufsteigen sah. Da wusste Ginro, dass er nicht nach einer Leiche suchte.]=],
		},
		{
			title = "Befreit aus dem Bau",
			hint = "Folgt der Spur des Kuriers bis zu ihrem Ende.",
			text = [=[Die Bündel hingen an einem Baum in den {link:camping}Lagern{/link} der Waldpfoten. Darin lag eine Notiz: {link:raschal-the-courier}Raschal{/link} hatte südlich der {link:gnolls}Gnolle{/link} Insekten gefunden und war selbst hingegangen, um sie zu sehen. In der Verwundenen Tiefe fand man ihn in einer Hülse versiegelt, betäubt, aber lebendig. Ginro sagte seinen Rettern, sie würden in ihm immer einen Freund haben.]=],
		},
	},
	mentions = {
		{ text = "Der vermisste Kurier" },
		{ text = "Bootswrack" },
		{ text = "Das enthüllte Messer" },
		{ text = "Psychometrische Lesung" },
		{ text = "Die {link:gnolls}Gnolle{/link} der Waldpfoten" },
		{ text = "{link:the-writhing-deep}Die verwundene Tiefe{/link}" },
		{ text = "Befreit aus dem Bau" },
		{ text = "Der Empfang eines Helden" },
	},
	bonds = {
		{ id = "raschal-the-courier", name = "Raschal der Kurier", note = "der Freund, nach dem er suchte" },
		{ id = "quintis-jonespyre", name = "Quintis Jonespyre", note = "las das Messer und schuldet ihm Spielgeld" },
		{ id = "latronicus-moonspear", name = "Latronicus Moonspear", note = "schickte ihm Hilfe" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "seine Generalin" },
	},
})

Translate("deDE", "raschal-the-courier", {
	title = "Raschal der Kurier",
	subtitle = "Kurier von Feathermoon",
	found = "Eine Hülse in der Verwundenen Tiefe",
	hint = "Folgt der Spur des verschollenen Kuriers bis zu ihrem Ende.",
	allegiance = "Schildwachen · Festung Feathermoon",
	aliases = { "Raschal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Raschal ist der Kurier, der Güter von der {link:feathermoon-stronghold}Festung Feathermoon{/link} nach {link:thalanaar}Thalanaar{/link} trägt. Er dient, seit die Generalin ihr Volk zum ersten Mal nach {link:feralas}Feralas{/link} führte, und er kennt das Land gut. Auf seiner letzten Reise begegnete er den Gnollen der Waldpfoten, erkannte ihre Not und ging allein nach Süden, um ihre Ursache zu sehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Raschals Bericht über die Insekten der Verwundenen Tiefe ging nach {link:darnassus}Darnassus{/link} und eine Abschrift an den {link:temple-of-the-moon}Tempel des Mondes{/link}. Er war die erste Warnung vor den {link:qiraji}Silithiden{/link} in {link:feralas}Feralas{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er trug die Pakete der Festung per Boot und zu Fuß nach {link:thalanaar}Thalanaar{/link}.
• Er ging in die {link:the-writhing-deep}Verwundene Tiefe{/link}, um zu erfahren, wie groß die Bedrohung war.
• Er wurde überwältigt, gelähmt in einer Hülse versiegelt und lebend befreit.]=],
		},
	},
	mentions = {
		{ text = "Befreit aus dem Bau" },
		{
			text = [=[Der Aufstieg der {link:qiraji}Silithiden{/link}, sein Bericht]=],
		},
		{
			text = [=[Lieferung nach {link:thalanaar}Thalanaar{/link}, sein nicht zugestelltes Paket]=],
		},
	},
	bonds = {
		{ id = "ginro-hearthkindle", name = "Ginro Hearthkindle", note = "hörte nie auf, nach ihm zu suchen" },
		{ id = "falfindel-waywarder", name = "Falfindel Waywarder", note = "wartete auf sein Paket" },
	},
})

Translate("deDE", "quintis-jonespyre", {
	title = "Quintis Jonespyre",
	subtitle = "Druide von Feathermoon",
	found = "Ein Baumhaus in der Festung Feathermoon",
	hint = "Steigt zum Baumhaus des Druiden der Festung hinauf.",
	allegiance = "Zirkel des Cenarius · Festung Feathermoon",
	aliases = { "Quintis" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Quintis Jonespyre ist der ansässige Druide der {link:feathermoon-stronghold}Festung Feathermoon{/link}, ein Diener von {link:malfurion-stormrage}Malfurion Stormrage{/link} und dem {link:cenarion-circle}Zirkel des Cenarius{/link}. Er lebt in einem Baumhaus über der Besatzung. Er studiert Flüche, und er besitzt eine ungewöhnliche Gabe: Wenn er einen Gegenstand berührt, kann er etwas von dessen Vergangenheit sehen.]=],
