		{
			title = "Bedeutung",
			text = [=[Quintis traut dem Erzdruiden nicht. {link:fandral-staghelm}Fandral Staghelm{/link} sammelt im Namen des Zirkels große Mengen des Krauts Morrowgrain, und Quintis hat bemerkt, dass Morrowgrain sich wie die Kräuter verhält, die in alten Flüchen verwendet wurden. Er und seine Kollegen vom Protektorat wollen wissen, warum.]=],
		},
		{
			title = "Taten",
			text = [=[• Er las das Messer des Kuriers {link:raschal-the-courier}Raschal{/link} und sah die letzten Stunden vor seinem Verschwinden.
• Er bittet Reisende, die Morrowgrain für {link:darnassus}Darnassus{/link} sammeln, ihm heimlich etwas davon zu bringen.]=],
		},
	},
	mentions = {
		{ text = "Jonespyres Bitte" },
		{ text = "Das Rätsel des Morrowgrain" },
		{
			text = [=[Morrowgrain für die {link:feathermoon-stronghold}Festung Feathermoon{/link}]=],
		},
		{ text = "Das enthüllte Messer" },
		{ text = "Psychometrische Lesung" },
	},
	bonds = {
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "der Erzdruide, dem er misstraut" },
		{ id = "ginro-hearthkindle", name = "Ginro Hearthkindle", note = "sein Kartenspielpartner" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "vom Protektorat" },
	},
})

Translate("deDE", "troyas-moonbreeze", {
	title = "Troyas Moonbreeze",
	subtitle = "Sucher der Ruinen",
	found = "Festung Feathermoon, bei seiner Frau und ihren Haustieren",
	hint = [=[Sprecht mit dem Gelehrten von Feathermoon, der die alten Ruinen durchsucht.]=],
	allegiance = "Festung Feathermoon",
	aliases = { "Troyas" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Troyas Moonbreeze und seine Frau {link:angelas-moonbreeze}Angelas{/link} erforschen die Ruinen, die überall in {link:feralas}Feralas{/link} liegen. Er glaubt, dass die Steine noch viel zu erzählen haben. Sein Kollege in {link:darnassus}Darnassus{/link} meint, er sehe in jedem Schutthaufen einen Schatz. In letzter Zeit geht er allein in die Obere Wildnis, was seiner Frau Angst macht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Troyas hatte zumindest einmal recht. Ein Stab, den er in den südlichen Ruinen fand, erwies sich als Schlüssel zum Equinex-Monolithen, und dieser öffnete sich.]=],
		},
		{
			title = "Taten",
			text = [=[• Er fand in den Ruinen einen schlicht aussehenden Stab und wollte ihn nicht hergeben.
• Er ließ sich das Buch {i}{link:feralas}Feralas{/link}: Eine Geschichte{/i} von der Hüterin des Wissens Daryn Lightwind schicken.
• Er hat begonnen, den Morrow Stone zu untersuchen, der aus dem Monolithen genommen wurde.]=],
		},
	},
	chapters = {
		{
			title = "Der Morrow Stone",
			hint = [=[Bringt den Stab des Gelehrten zum Monolithen in den nördlichen Ruinen.]=],
			text = [=[Geladen mit der Essenz von vier alten Flammen, wurde der Stab zu schwer von Macht, um ihn zu halten. Bei seiner Berührung öffnete der Equinex-Monolith eine kleine Tür, und darin lag ein funkelnder Stein. Troyas las, dass er Morrow Stone genannt wurde. Er kennt seinen Zweck nicht. Er weiß nur, dass niemand einen gewöhnlichen Stein so sorgfältig verbirgt.]=],
		},
	},
	mentions = {
		{ text = "Auf der Suche nach Wissen" },
		{ text = "Zurück zu Troyas" },
		{ text = "Der Stab von Equinex" },
		{ text = "Der Morrow Stone" },
	},
	bonds = {
		{ id = "angelas-moonbreeze", name = "Angelas Moonbreeze", note = "seine Frau" },
	},
})

Translate("deDE", "angelas-moonbreeze", {
	title = "Angelas Moonbreeze",
	subtitle = "Sucherin der Ruinen",
	found = "Festung Feathermoon, neben ihrem Mann",
	hint = [=[Sprecht mit der Gelehrten, die um die Sicherheit ihres Mannes bangt.]=],
	allegiance = "Festung Feathermoon",
	aliases = { "Angelas" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Angelas Moonbreeze teilt die Liebe ihres Mannes {link:troyas-moonbreeze}Troyas{/link} zu alten Ruinen und viel von seiner Gelehrsamkeit. Seine Sorglosigkeit teilt sie nicht. Als er begann, allein in die Obere Wildnis zu wandern, wo die Gordunni-{link:ogres}Oger{/link} herrschen, bat sie still andere, ihm den Weg freizumachen und ihm nichts davon zu sagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Angelas' Studien reichen weit über {link:feralas}Feralas{/link} hinaus. Sie weiß von einem Tempel unter der Erde, dorthin verbannt von Mächten, größer als alle, die sie je gesehen hat, und von einem Goblingelehrten, der in ihm gewandelt ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie bat darum, die {link:ogres}Oger{/link} der Oberen Wildnis um ihres Mannes willen zurückzudrängen.
• Sie schickt jene, die den {link:temple-of-atal-hakkar}Versunkenen Tempel{/link} suchen, zum Goblin {link:marvon-rivetseeker}Marvon Rivetseeker{/link} in {link:tanaris}Tanaris{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:high-wilderness}Die obere Wildnis{/link}" },
		{ text = "Der Versunkene Tempel" },
	},
	bonds = {
		{ id = "troyas-moonbreeze", name = "Troyas Moonbreeze", note = "ihr Mann" },
	},
})

Translate("deDE", "kindal-moonweaver", {
	title = "Kindal Moonweaver",
	subtitle = "Beschützerin der Sprite Darter",
	found = "Ein Grat über dem Truppenlager der Grimmtotem",
	hint = [=[Findet die Bogenschützin der Nachtelfen, die das Lager der Grimmtotem von oben beobachtet.]=],
	allegiance = "Darnassus",
	aliases = { "Kindal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kindal Moonweaver und ihre Gefährtin {link:jer-kai-moonweaver}Jer'kai{/link} lagern auf einem Grat über dem {link:grimtotem-compound}Truppenlager der Grimmtotem{/link}. Von dort haben sie beobachtet, wie {link:grimtotem-clan}die Grimmtotem{/link} die Feendrachen von {link:feralas}Feralas{/link} in Käfige sperrten. Die beiden allein konnten nicht in das Lager eindringen. Mit Hilfe ging Kindal selbst hinein.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kindal ist eine Beschützerin der Wildnis im ältesten Sinne ihres Volkes. Als die Drachen befreit waren, ruhte sie nicht. Sie wandte sich dem Gegenschlag zu, damit sie frei blieben.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie führte die Rettung der Sprite Darter aus dem Pferch der Grimmtotem an.
• Sie rettete ein Nest mit Eiern von Sprite Dartern, deren Mutter gestorben war, und gibt sie jenen, die für sie sorgen wollen.]=],
		},
	},
	mentions = {
		{ text = "Freiheit für alle Geschöpfe" },
		{ text = "Eine Waise sucht ein Zuhause" },
	},
	bonds = {
		{ id = "jer-kai-moonweaver", name = "Jer'kai Moonweaver", note = "ihre Gefährtin" },
		{ id = "agnar-beastamer", name = "Agnar Beastamer", note = "hilft, ihre Eier auszubrüten" },
	},
})

Translate("deDE", "jer-kai-moonweaver", {
	title = "Jer'kai Moonweaver",
	subtitle = "Priesterin Elunes",
	found = "Ein Grat über dem Truppenlager der Grimmtotem",
	hint = [=[Findet die Priesterin, die mit ihrer Gefährtin das Lager der Grimmtotem beobachtet.]=],
	allegiance = "Darnassus · Tempel des Mondes",
	aliases = { "Jer'kai" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jer'kai Moonweaver ist eine Priesterin Elunes, die {link:tyrande-whisperwind}Tyrande Whisperwind{/link} dient. Mit {link:kindal-moonweaver}Kindal{/link} hält sie Wache über das {link:grimtotem-compound}Truppenlager der Grimmtotem{/link}. Sie fragt sich, ob die anderen {link:tauren}Tauren{/link} {link:grimtotem-clan}die Grimmtotem{/link} missbilligen, und vermutet, dass viele Völker Azeroths dunklere Verwandte haben, die sie lieber nicht anerkennen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jer'kais Siegelring trägt ihre Nachrichten bis zur Hohepriesterin selbst, und {link:tyrande-whisperwind}Tyrande{/link} hat versprochen, dass ihre Späher nach den beiden Beschützerinnen sehen werden.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie kämpfte an Kindals Seite gegen die Plünderer, Naturkundler und Schamanen der Grimmtotem.
• Sie schickte {link:tyrande-whisperwind}Tyrande{/link} ihren Siegelring als Beweis, dass es den beiden gut ging.]=],
		},
	},
	mentions = {
		{ text = "Gerechtigkeit üben" },
		{ text = "Gerechtigkeit üben, der Siegelring" },
	},
	bonds = {
		{ id = "kindal-moonweaver", name = "Kindal Moonweaver", note = "ihre Gefährtin" },
		{ id = "tyrande-whisperwind", name = "Tyrande Whisperwind", note = "ihre Hohepriesterin" },
	},
})

Translate("deDE", "rockbiter", {
	title = "Rockbiter",
	subtitle = "Der Riesenwächter",
	found = "Ein Lager unterhalb der Zwillingskolosse",
	hint = [=[Sucht den Riesen, der die kleine Elfe verloren hat, auf die er aufpassen sollte.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rockbiter ist ein Riese der nördlichen Hügel von {link:feralas}Feralas{/link}, und ein sanfter. Er sollte über {link:shay-leafrunner}Shay Leafrunner{/link} wachen, eine junge Nachtelfe, die gern umherwandert. Eben war sie noch neben ihm in den Ruinen nördlich seines Lagers. Im nächsten Augenblick war sie fort, und er wusste nicht, was er tun sollte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[In einem Wald, in dem die meisten Riesen gefährlich sind, erinnert Rockbiter daran, dass nicht alle es sind. Seine Freundschaft mit einem kleinen Elfenmädchen ist eine der freundlicheren Geschichten von {link:feralas}Feralas{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bat einen Reisenden, Shay zu finden, da kleine Beine schneller sind als seine.
• Er verwahrt nun ihre Glocke, damit er sie zurückrufen kann.]=],
		},
	},
	mentions = {
		{ text = "Der Riesenwächter" },
		{ text = "Die umherwandernde Shay" },
	},
	bonds = {
		{ id = "shay-leafrunner", name = "Shay Leafrunner", note = "das Mädchen, das er beschützt" },
	},
})

Translate("deDE", "shay-leafrunner", {
	title = "Shay Leafrunner",
	subtitle = "Ein umherwanderndes Mädchen",
	found = "Die Ruinen von Rabenwind",
	hint = [=[Findet das Nachtelfenmädchen, das in die nördlichen Ruinen gewandert ist.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shay Leafrunner ist eine junge Nachtelfe, die nicht anders kann, als umherzuwandern. Es gibt immer noch etwas anderes zu sehen, und sie vergisst, wohin sie wollte. Ihr Freund, der Riese {link:rockbiter}Rockbiter{/link}, soll sie beschützen. Als sie in die {link:ruins-of-ravenwind}Ruinen von Rabenwind{/link} wanderte, bemerkte sie nicht einmal, dass sie sich verirrt hatte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Shay bewahrt einen Schatz in einer Truhe auf: eine Glocke, deren Klang sie liebt. Wer immer sie läutet, so hat sie versprochen, zu dem wird sie gelaufen kommen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie wanderte von {link:rockbiter}Rockbiter{/link} fort in die Ruinen der {link:harpies}Harpyien{/link}.
• Sie gab ihre Glocke her, damit man sie nach Hause führen konnte.]=],
		},
	},
	mentions = {
		{ text = "Die umherwandernde Shay" },
	},
	bonds = {
		{ id = "rockbiter", name = "Rockbiter", note = "ihr Beschützer" },
	},
})

Translate("deDE", "hadoken-swiftstrider", {
	title = "Hadoken Swiftstrider",
	subtitle = "Krieger von Camp Mojache",
	found = "Camp Mojache",
	hint = [=[Sprecht mit dem Kriegsführer, der Camp Mojache gegen die Gnolle hält.]=],
	allegiance = "Horde · Camp Mojache",
	aliases = { "Hadoken" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hadoken Swiftstrider befehligt die Verteidigung von {link:camp-mojache}Camp Mojache{/link}. Für die Frage, ob die {link:gnolls}Gnolle{/link} der Waldpfoten nach {link:feralas}Feralas{/link} gehören, hat er keine Geduld. Sie greifen sein Lager an, und wenn die {link:horde}Horde{/link} nicht standhält, wird sie aus der Region vertrieben. Er ist ein Veteran, der viele Schlachtpläne gelesen hat, und er erkennt einen verzweifelten Feind, wenn er einen sieht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hadoken war der Erste der {link:horde}Horde{/link}, der erkannte, dass die {link:gnolls}Gnolle{/link} nicht die wahre Bedrohung waren. Er folgte ihrer Furcht nach Süden und fand die Zukk'ash, und sein Bericht über sie erreichte {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befahl, die Alphatiere der Waldpfoten rasch nacheinander niederzustrecken, um die {link:gnolls}Gnolle{/link} ins Chaos zu stürzen.
• Er schickte Suchende nach den Schlachtplänen der Gnolle.
• Er befahl, die Zukk'ash der Verwundenen Tiefe zu lichten und ihr größtes Tier, {link:stinglasher}Stinglasher{/link}, zur Untersuchung aufzuschneiden.
• Er sandte den Bericht des Lagers über die Insekten an Zilzibin Drumlore in {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Krieg gegen die Waldpfoten",
			hint = "Treibt die Gnolle zurück, die Camp Mojache überfallen.",
			text = [=[Die Waldpfoten hatten das Lager schon immer überfallen, und die {link:horde}Horde{/link} hatte sie immer abgewehrt. In letzter Zeit waren die Überfälle wild und unablässig geworden, als hätten die {link:gnolls}Gnolle{/link} keinen anderen Ort, an den sie gehen konnten. Hadoken wollte sie mit einem einzigen scharfen Schlag brechen. Es gelang, für eine Weile. Es ließ ihn auch fragen, was sie in eine solche Raserei getrieben hatte.]=],
		},
		{
			title = "Die Schlachtpläne",
			hint = [=[Findet die Schlachtpläne der Gnolle in ihren südlichen Lagern.]=],
			text = [=[Die Karte der {link:gnolls}Gnolle{/link} erzählte die Geschichte. Die meisten ihrer Pfeile wiesen nach Süden, fort von {link:camp-mojache}Camp Mojache{/link}, und neben der Zeichnung eines großen Insekts standen Reihen von Strichen: ihre Toten. Die Waldpfoten führten einen Krieg an zwei Fronten, und den, den sie verloren, führten sie nicht gegen die {link:horde}Horde{/link}.]=],
		},
		{
			title = "Die Zukk'ash",
			hint = [=[Bringt den Bericht des Lagers über die Insekten nach Orgrimmar.]=],
			text = [=[Hadoken kümmerte es nicht, ob die Insekten denken konnten. Sie trieben die {link:gnolls}Gnolle{/link} in sein Lager, und darum waren sie sein Feind. Als seine Erkenntnisse Zilzibin Drumlore in {link:orgrimmar}Orgrimmar{/link} erreichten, gab der Goblin den Insekten ihren wahren Namen, {link:qiraji}Silithiden{/link}, und warnte, dass die {link:horde}Horde{/link} sie viel zu lange missachtet habe.]=],
		},
	},
	mentions = {
		{ text = "Krieg gegen die Waldpfoten" },
		{ text = "Schlag gegen die Alphatiere" },
		{ text = "Untersuchung der Waldpfoten" },
		{ text = "Die Schlachtpläne" },
		{ text = "Befall durch die Zukk'ash" },
		{ text = "{link:stinglasher}Stinglasher{/link}" },
		{ text = "Bericht über die Zukk'ash" },
	},
	bonds = {
		{ id = "stinglasher", name = "Stinglasher", note = "das Tier, das er untersucht haben wollte" },
		{ id = "rok-orhan", name = "Rok Orhan", note = "kämpft an seiner Seite gegen die Oger" },
		{ id = "shandris-feathermoon", name = "Shandris Feathermoon", note = "hält die Festung der Allianz im Westen" },
	},
})

Translate("deDE", "rok-orhan", {
	title = "Rok Orhan",
	subtitle = "Feind der Gordunni",
	found = "Camp Mojache",
	hint = [=[Sprecht mit dem Orc von Camp Mojache, der gegen die Oger des Nordens kämpft.]=],
	allegiance = "Horde · Orgrimmar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Rok Orhan ist ein Orckrieger von {link:camp-mojache}Camp Mojache{/link}, der geschworen hat, die Gordunni-{link:ogres}Oger{/link} zurückzutreiben. Er sieht ihr Zeichen überall im Wald und glaubt, dass das Land erst heilen wird, wenn sie fort sind. Er kennt seinen Feind gut, doch er gibt nicht vor, sich auf Magie zu verstehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rok Orhan verschaffte der {link:horde}Horde{/link} den ersten Einblick in die Magie der Magierlords der Gordunni, und seine Funde gingen an die Magier von {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickte Krieger gegen den {link:gordunni-outpost}Außenposten der Gordunni{/link} und dann gegen die {link:ogres}Oger{/link} der Oberen Wildnis.
• Er untersuchte eine Schriftrolle, die eine dunkle Zeremonie der Magierlords beschrieb.
• Er schickte eine Gordunni-Kugel an den Magier Uthel'nay von der Darkbriar Lodge, der sie für mächtig und gefährlich befand.]=],
		},
	},
	mentions = {
		{ text = "Die {link:ogres}Oger{/link} von {link:feralas}Feralas{/link}" },
		{
			text = [=[Die {link:ogres}Oger{/link} von {link:feralas}Feralas{/link}, in der Oberen Wildnis]=],
		},
		{ text = "Die Schriftrolle der Gordunni" },
		{ text = "Dunkle Zeremonie" },
		{ text = "Die Kugel der Gordunni" },
	},
	bonds = {
		{ id = "hadoken-swiftstrider", name = "Hadoken Swiftstrider", note = "hält das Lager an seiner Seite" },
	},
})

Translate("deDE", "talo-thornhoof", {
	title = "Talo Thornhoof",
	subtitle = "Alter Jäger von Camp Mojache",
	found = "Camp Mojache",
	hint = [=[Sprecht mit dem alten Taurenjäger, der noch immer die Schreie der Harpyien hört.]=],
	allegiance = "Horde · Thunder Bluff",
	aliases = { "Talo" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Talo Thornhoof war einst ein Jäger, der kein Geschöpf fürchtete. Dann erwischten ihn die Northspring-{link:harpies}Harpyien{/link} allein im Wald, und er entkam nur knapp mit dem Leben. Er ist seitdem nicht mehr derselbe. Der Hass hat ihn in all den Jahren nicht verlassen, und er will, dass die Harpyien bezahlen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Talo studiert seine Feinde, um von ihnen zu lernen. Er glaubt, dass die Tiere des {link:felwood}Teufelswalds{/link}, von der Verderbnis in den Wahnsinn getrieben, auch stärker geworden sind, und er will wissen, wie.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verlangte Rache an den Northspring-{link:harpies}Harpyien{/link} und das dunkle Herz ihrer Königin, {link:edana-hatetalon}Edana Hatetalon{/link}.
• Er schickte Jäger aus, um die verderbten Tiere des Teufelswalds zu vermessen.
• Er will, dass das Netz der Magierin Lethtendris aus {red:dire-maul}Düsterbruch{/red} geholt und weiseren Hütern übergeben wird.]=],
		},
	},
	mentions = {
		{ text = "Rache an den Northspring" },
		{ text = "Dunkles Herz" },
		{ text = "Die Stärke der Verderbnis" },
		{ text = "Lethtendris' Netz" },
	},
	bonds = {
		{ id = "edana-hatetalon", name = "Edana Hatetalon", note = "die Harpyienkönigin, die er hasst" },
	},
})

Translate("deDE", "witch-doctor-uzer-i", {
	title = "Hexendoktor Uzer'i",
	subtitle = "Hexendoktor von Camp Mojache",
	found = "Camp Mojache",
	hint = [=[Sprecht mit dem Hexendoktor der Trolle in Camp Mojache, der ein besonderes Gefäß sucht.]=],
	allegiance = "Horde · Camp Mojache",
	aliases = { "Uzer'i" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hexendoktor Uzer'i ist ein Troll von {link:camp-mojache}Camp Mojache{/link} und ein Meister einer alten und beunruhigenden Kunst. Er kennt den Muisek, den Geist, den ein Geschöpf zurücklässt, wenn es gewaltsam stirbt. Ein solcher Geist, so lehrt er, kann entkommen, Rache suchen und sogar in der Gestalt eines größeren Tieres zurückkehren. Uzer'i hat einen Weg gefunden, dies zu verhindern. Ein Geschöpf, das im Augenblick seines Todes geschrumpft und gefangen wird, kann seinen Muisek nicht freigeben, und ein gefangener Muisek lässt sich nutzen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Uzer'is Werk ist eine Waffe, die gegen die {link:night-elves}Nachtelfen{/link} gerichtet ist. Er wählt seine Geschöpfe nach ihrer Verbindung zu den Kaldorei: die Wildekin, einst die Lieblinge Elunes; die Hippogryphen, ihre treuen Reittiere; die Feendrachen, ihre Verbündeten; die Treants, ihre Beschützer; und die Bergriesen, die von ihren Gipfeln herabstiegen, um ihnen gegen die {link:burning-legion}Brennende Legion{/link} beizustehen. Ihre Stärke, sagt er, solle ebenso der {link:horde}Horde{/link} dienen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er tauschte den Schrumpfkopf eines Zwergs bei {link:neeru-fireblade}Neeru Fireblade{/link} in {link:orgrimmar}Orgrimmar{/link} gegen die Kräuter, die sein Gefäß brauchte.
• Er schickte Jäger bis ins {link:the-hinterlands}Hinterland{/link}, um den Muisek der Wildekin einzufangen.
• Er versiegelte die gefangenen Geister in Waffen.]=],
		},
	},
	chapters = {
		{
			title = "Das Muisekgefäß",
			hint = [=[Bringt dem Hexendoktor die Kräuter, die er aus Orgrimmar erwartet.]=],
			text = [=[{link:neeru-fireblade}Neeru Fireblade{/link} hatte die Kräuter vorbereitet, und er war zufrieden mit dem Kopf, den er dafür erhielt. Uzer'i vollzog sein Ritual über dem Gefäß sogleich. Seine erste Probe lag weit entfernt, unter den Eulenbestien des Hinterlands, und sie sollte sowohl das Ritual als auch den Jäger prüfen, der das Gefäß trug.]=],
		},
		{
			title = "Waffen des Geistes",
			hint = "Vervollständigt die Geistersammlung des Hexendoktors.",
			text = [=[Hippogryph, Feendrache, Treant und Bergriese: Einer nach dem anderen wurden die Verbündeten der {link:night-elves}Nachtelfen{/link} geschrumpft und gefangen. Mit gesplittertem Holz, Mineralien, Sehnen und Metallsplittern band Uzer'i ihre Geister für immer in die Waffen, die er schmiedete.]=],
		},
	},
	mentions = {
		{ text = "Eine seltsame Bitte" },
		{ text = "Zurück zu Hexendoktor Uzer'i" },
		{ text = "Die Prüfung des Gefäßes" },
		{ text = "Muisek des Hippogryphen" },
		{ text = "Muisek des Feendrachen" },
		{ text = "Muisek des Treants" },
		{ text = "Muisek des Bergriesen" },
		{ text = "Natürliche Materialien" },
		{ text = "Waffen des Geistes" },
	},
	bonds = {
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "tauscht Kräuter mit ihm" },
	},
})

Translate("deDE", "krueg-skullsplitter", {
	title = "Krueg Skullsplitter",
	subtitle = "Gesandter von Orgrimmar",
	found = "Camp Mojache",
	hint = [=[Sprecht mit dem Orc von Camp Mojache, der einen feinen Umhang für seine Gefährtin will.]=],
	allegiance = "Horde · Orgrimmar",
	aliases = { "Krueg" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Krueg Skullsplitter ist ein {link:orcs}Orc{/link}, der mit seinen Gefährten im Auftrag ihrer Herren in {link:orgrimmar}Orgrimmar{/link} nach {link:feralas}Feralas{/link} kam. Sein Herz ist zu Hause bei seiner Gefährtin Korrin, die feine Kleider liebt, und er will ihr einen Umhang aus Feendrachenflügeln machen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kruegs Umhang führte zu einem dunkleren Fund. Als er erfuhr, dass {link:grimtotem-clan}die Grimmtotem{/link} in {link:feralas}Feralas{/link} waren, schlug seine Stimmung sofort um, und er sandte die Nachricht nach {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelt die Flügel von Sprite Dartern für Korrins Umhang.
• Er setzte ein Kopfgeld auf Hörner der Grimmtotem aus und gab zu, voreilig gesprochen zu haben.
• Er sendet Nachricht über {link:grimtotem-clan}die Grimmtotem{/link} an Belgrom Rockmaul im Tal der Ehre.]=],
		},
