	hint = [=[Sucht den Ältesten, der zwischen den Ruinen von Lariss' Pavillon wohnt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Azj'Tordin ist ein Ältester von Eldre'Thalas, der dem Griff seines gefallenen Prinzen entkam. Er bezahlte seine Freiheit mit seiner Unsterblichkeit, und er bereut es nicht. Nun lebt er in {link:lariss-pavilion}Lariss' Pavillon{/link}, zwischen alten Steinen im östlichen Wald.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Azj'Tordin verließ {red:dire-maul}Düsterbruch{/red} aus eigenem Entschluss und bezahlte dafür. In der Hast seiner Flucht raubte ihm ein dämonischer Wichtel namens Pusillin sein Buch der Beschwörungen und einen Schlüssel zu den alten Hallen der Stadt. Der Schlüssel kümmert ihn nicht mehr. Er will sein Buch zurück.]=],
		},
		{
			title = "Taten",
			text = [=[• Er floh vor dem gefallenen Prinzen von Eldre'Thalas.
• Er bittet darum, sein gestohlenes Buch dem Wichtel im Warpwood Quarter wieder abzunehmen.]=],
		},
	},
	mentions = {
		{ text = "Pusillin und der Älteste Azj'Tordin" },
