	bonds = {
		{ id = "tortheldrin", name = "Tortheldrin", note = "der gefallene Prinz, vor dem er floh" },
	},
})

Translate("deDE", "sage-korolusk", {
	title = "Weiser Korolusk",
	subtitle = "Sucher elfischer Überlieferung",
	found = "Camp Mojache",
	hint = [=[Sprecht mit dem Weisen von Camp Mojache, der einen verschollenen elfischen Meister sucht.]=],
	allegiance = "Horde · Camp Mojache",
	aliases = { "Korolusk" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Weise Korolusk ist einer langen Spur nach {link:feralas}Feralas{/link} gefolgt. Er sucht Kariel Winthalus, einen elfischen Meister, der mit uralten elfischen Artefakten vor der Verwüstung seiner Heimat floh. Die Spur führte von den Ruinen von {link:quel-thalas}Quel'Thalas{/link} durch die {link:burning-steppes}Brennende Steppe{/link} und über das Meer, und sie endet, so glaubt Korolusk, in den Hallen von Eldre'Thalas.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Korolusk und der Gelehrte {link:scholar-runethorn}Runethorn{/link} von {link:feathermoon-stronghold}Feathermoon{/link} jagen denselben Mann um desselben Wissens willen, der eine für die {link:horde}Horde{/link}, der andere für die {link:alliance}Allianz{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bittet darum, Düsterbruch nach Kariel zu durchsuchen, lebend oder tot.]=],
		},
	},
	mentions = {
		{ text = "Elfische Legenden" },
	},
	bonds = {
		{ id = "scholar-runethorn", name = "Gelehrter Runethorn", note = "sucht denselben Meister" },
	},
})

