	},
	bonds = {
		{ id = "sage-korolusk", name = "Weiser Korolusk", note = "sucht denselben Meister" },
	},
})

Translate("deDE", "falfindel-waywarder", {
	title = "Falfindel Waywarder",
	subtitle = "Druide von Thalanaar",
	found = "Thalanaar, am östlichen Rand von Feralas",
	hint = [=[Sucht den Druiden, der die Raststation am östlichen Waldrand hütet.]=],
	allegiance = "Zirkel des Cenarius · Thalanaar",
	aliases = { "Falfindel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Falfindel Waywarder ist ein Druide der {link:night-elves}Nachtelfen{/link}, der {link:thalanaar}Thalanaar{/link} hütet, die einsame Raststation, wo die Wälder von {link:feralas}Feralas{/link} auf die Schluchten von {link:thousand-needles}Tausend Nadeln{/link} treffen. Die Bewahrer des Steinkrallengebirges nennen ihn groß und weise. Man sagt, er könne die großen Geister des Waldes rufen, damit sie verwundeten Landen zu Hilfe kommen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Von seinem stillen Posten aus wacht Falfindel über mehr als {link:feralas}Feralas{/link}. Seine Sorge reicht bis ins {link:the-barrens}Brachland{/link}, wo die Ruhestätte des Eberhalbgottes Agamaggan verderbt wurde, und nach Norden bis ins {link:stonetalon-mountains}Steinkrallengebirge{/link}, dessen Bewahrer ihn um Hilfe angefleht hat.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erforscht, was die Ruhestätte von Agamaggan im südlichen {link:the-barrens}Brachland{/link} verderbt hat.
• Er schickte andere gegen die Vettel {link:charlga-razorflank}Charlga Razorflank{/link} im {link:razorfen-kraul}Kral von Razorfen{/link}.
• Er folgt der Bitte von {link:keeper-albagorm}Bewahrer Albagorm{/link}, Waldgeister in das verbrannte Tal zu senden.
• Er wartet auf die Vorräte, die Kuriere von {link:feathermoon-stronghold}Feathermoon{/link} quer durch {link:feralas}Feralas{/link} tragen.]=],
		},
	},
	chapters = {
		{
			title = "Die Vettel des Krals",
			hint = "Bringt das Tagebuch eines toten Zwergs nach Thalanaar.",
			text = [=[Das Tagebuch von Henrig Lonebrow berichtete Falfindel vom Druiden {link:heralath-fallowbrook}Heralath{/link}, der im {link:razorfen-kraul}Kral{/link} gefangen war, und von einer Vettel, die mit jedem Tag stärker wurde. Es war keine Zeit, {link:darnassus}Darnassus{/link} um Hilfe zu bitten. Als das Medaillon der Vettel zu ihm zurückkam, wagte er zu hoffen, dass seine Studien weitergehen könnten, auch wenn er fürchtete, die Antwort darauf werde Verrat sein.]=],
		},
		{
			title = "Ein Ruf aus dem Steinkrallengebirge",
			hint = [=[Bringt die Bitte von Bewahrer Albagorm zum Druiden von Thalanaar.]=],
			text = [=[Die {link:harpies}Harpyien{/link} des verbrannten Tals waren zerschlagen, doch sie würden zurückkehren, und Samen allein konnten {link:stranglethorn-vale}das Tal{/link} nicht heilen, bevor sie es taten. {link:keeper-albagorm}Albagorm{/link} sandte Nachricht über halb {link:kalimdor}Kalimdor{/link} zu Falfindel. Der Druide verschwendete keine Worte. Er wandte sich sogleich daran, Hilfe aus dem großen Wald zu rufen.]=],
		},
		{
			title = "Das verspätete Paket",
			hint = "Bringt das verlorene Paket des Kuriers nach Thalanaar.",
			text = [=[Das Paket aus {link:feathermoon-stronghold}Feathermoon{/link} kam spät und durch die Hand eines Fremden. Falfindel ahnte sofort, dass {link:raschal-the-courier}Raschal{/link}, dem üblichen Kurier, etwas zugestoßen war. Er hatte seinen eigenen Verdacht: Die Waldpfoten waren in letzter Zeit unruhig geworden, aufgewühlt von etwas im Süden.]=],
		},
	},
	mentions = {
		{ text = "Lonebrows Tagebuch" },
		{ text = "Die Vettel des Krals" },
		{
			text = [=[Die Rückgewinnung des verbrannten Tals, die Bitte aus dem {link:stonetalon-mountains}Steinkrallengebirge{/link}]=],
		},
		{ text = "Lieferung nach {link:thalanaar}Thalanaar{/link}" },
	},
	bonds = {
		{ id = "keeper-albagorm", name = "Bewahrer Albagorm", note = "bat um seine Hilfe" },
		{ id = "heralath-fallowbrook", name = "Heralath Fallowbrook", note = "der im Kral gefangene Druide" },
		{ id = "charlga-razorflank", name = "Charlga Razorflank", note = "Feindin" },
		{ id = "raschal-the-courier", name = "Raschal der Kurier", note = "sein üblicher Kurier" },
	},
})

Translate("deDE", "zorbin-fandazzle", {
