		},
	},
	mentions = {
		{ text = "Geschrumpfte Riesen" },
		{ text = "Schon wieder geschrumpfte Riesen" },
		{ text = "Treibstoff für den Schrumpfer" },
		{ text = "Neuer Treibstoff für den Schrumpfer" },
	},
	bonds = {
		{ id = "rockbiter", name = "Rockbiter", note = "einer der Riesen, die er lieber schrumpfen würde" },
	},
})

