	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Lethlas ist ein großer grüner Drache, der das {link:dream-bough}Traum-Geäst{/link} im Norden von {link:feralas}Feralas{/link} bewacht. Mit einem anderen seiner Art, Dreamroarer, und den Drachkin des Jademirsees hält er den Baum und sein Tor zum {link:emerald-dream}Smaragdgrünen Traum{/link} von allen fern, die sich nähern.]=],
